#include "contract_test.h"
#include "forward_controller.h"
int main(){using namespace laya;ForwardController f;BufferRef wi=test::ref(Buffer::WI),df=test::ref(Buffer::DEC_FF),cand=test::ref(Buffer::HEAD_WORK),act=test::ref(Buffer::HEAD_WORK);
  test::require(f.accept_task(1),"first task");test::require(!f.accept_task(2),"one in flight");TaskDone done{1,Status::OK,0,UINT64_MAX,8,0,OutputUnit::F32,true};test::require(f.retire_task(done,8,OutputUnit::F32),"retire");test::require(!f.accept_task(1),"no task reuse");
  test::require(f.reserve(wi,0,2,Content::F32),"WI reserve");test::require(!f.reserve(df,0,1,Content::F32),"WI/DEC_FF alias");test::require(f.cover(wi,0,0,1),"first row");test::require(!f.publish(wi,0,true),"coverage incomplete");test::require(f.cover(wi,0,1,1)&&f.publish(wi,0,true),"publish complete");test::require(f.acquire_read(wi,0,Content::F32),"read");test::require(!f.release_storage(wi,0),"reader holds");test::require(f.release_read(wi,0)&&f.release_storage(wi,0),"release WI");test::require(f.reserve(df,0,1,Content::F32),"DEC_FF reuse");
  test::require(f.reserve(cand,3,1,Content::F32)&&f.cover(cand,3,0,1)&&f.publish(cand,3,true),"candidate ready");test::require(f.reserve(act,2,1,Content::F32)&&f.cover(act,2,0,1)&&f.publish(act,2,true),"act coexist");test::require(f.ready(cand,3),"candidate survives act");
  BufferRef type=test::ref(Buffer::TYPE_ROWS);test::require(f.reserve(type,0,3,Content::F32)&&f.type_row(type,2),"type2 only");test::require(f.type_valid(type,2)&&!f.type_valid(type,1)&&!f.ready(type,0),"type-specific read");
  test::require(!f.acquire_read(type,0,Content::F32),"generic type read denied");test::require(!f.acquire_type_read(type,1),"unloaded type denied");
  test::require(f.type_row(type,1),"second type loaded");test::require(f.acquire_type_read(type,2),"loaded type read");
  test::require(!f.release_type_read(type,1),"wrong loaded type cannot release type2 lock");
  test::require(!f.release_read(type,0),"generic release cannot release type lock");
  test::require(!f.type_row(type,0),"no fill during type read");
  test::require(f.release_type_read(type,2)&&f.type_row(type,0),"fill after correct release");
  test::require(f.acquire_type_read(type,0)&&f.acquire_type_read(type,1),"independent type locks");
  test::require(f.release_type_read(type,0)&&!f.release_storage(type,0),"remaining type lock holds buffer");
  test::require(f.release_type_read(type,1),"release remaining type lock");
  for(unsigned i=0;i<UINT8_MAX;i++)test::require(f.acquire_type_read(type,2),"type reader capacity");
  test::require(!f.acquire_type_read(type,2),"type reader overflow denied");
  for(unsigned i=0;i<UINT8_MAX;i++)test::require(f.release_type_read(type,2),"type reader release");
  test::require(f.release_storage(type,0),"type readers fully released");
  ForwardController count_limit;BufferRef count_ref=test::ref(Buffer::HEAD_WORK);
  test::require(count_limit.reserve(count_ref,3,1,Content::F32)&&count_limit.cover(count_ref,3,0,1)&&count_limit.publish(count_ref,3,true),"generic reader fixture");
  for(unsigned i=0;i<UINT8_MAX;i++)test::require(count_limit.acquire_read(count_ref,3,Content::F32),"generic reader capacity");
  test::require(!count_limit.acquire_read(count_ref,3,Content::F32),"generic reader overflow denied");
  for(unsigned i=0;i<UINT8_MAX;i++)test::require(count_limit.release_read(count_ref,3),"generic reader release");
  test::require(count_limit.release_storage(count_ref,3),"generic readers fully released");
  test::require(!f.begin_inplace(type,{Buffer::TYPE_ROWS,0,2},0,3,Content::F32),"type inplace denied");

  ForwardController pipeline;
  BufferRef q0=test::ref(Buffer::QKV,0),q1=test::ref(Buffer::QKV,1),kv=test::ref(Buffer::KV),score=test::ref(Buffer::SCORE_PROB);
  QKTask qk;qk.qkv_ref={q0,q1};qk.kv=kv;
  for(auto q:{q0,q1})test::require(pipeline.reserve(q,0,1,Content::QKV_RAW)&&pipeline.cover(q,0,0,1)&&pipeline.publish(q,0,true),"QKV raw ready");
  test::require(pipeline.reserve(kv,0,1,Content::F32)&&pipeline.cover(kv,0,0,1)&&pipeline.publish(kv,0,true),"KV ready");
  test::require(!pipeline.validate_inputs(qk),"RAW cannot feed QK");
  for(auto q:{q0,q1}){BufferRef next=q;next.epoch=2;test::require(pipeline.begin_inplace(q,next,0,1,Content::QKV_FINAL)&&pipeline.cover(next,0,0,1)&&pipeline.publish_inplace(next,0,true),"RAW to FINAL");}
  qk.qkv_ref[0].epoch=qk.qkv_ref[1].epoch=2;
  test::require(pipeline.validate_inputs(qk),"FINAL feeds QK");
  test::require(pipeline.reserve(score,0,1,Content::SCORE)&&pipeline.cover(score,0,0,1)&&pipeline.publish(score,0,true),"SCORE ready");
  AVTask av;av.prob=score;av.kv=kv;
  test::require(!pipeline.validate_inputs(av),"SCORE cannot feed AV");
  BufferRef prob=score;prob.epoch=2;
  test::require(pipeline.begin_inplace(score,prob,0,1,Content::PROB)&&pipeline.cover(prob,0,0,1)&&pipeline.publish_inplace(prob,0,true),"SCORE to PROB");
  av.prob=prob;test::require(pipeline.validate_inputs(av),"PROB feeds AV");
  BufferRef a=test::ref(Buffer::A8),w=test::ref(Buffer::WEIGHT);LinearTask linear;linear.a=a;linear.w=w;
  test::require(pipeline.reserve(a,0,1,Content::F32)&&pipeline.cover(a,0,0,1)&&pipeline.publish(a,0,true),"wrong A8 content fixture");
  test::require(pipeline.reserve(w,0,1,Content::Q8_WEIGHT)&&pipeline.cover(w,0,0,1)&&pipeline.publish(w,0,true),"W ready");
  test::require(!pipeline.validate_inputs(linear),"F32 cannot feed Q8 Linear");
  test::require(pipeline.release_storage(a,0),"release wrong A8");a.epoch=2;linear.a=a;
  test::require(pipeline.reserve(a,0,1,Content::Q8_TILE)&&pipeline.cover(a,0,0,1)&&pipeline.publish(a,0,true),"A8 ready");
  test::require(pipeline.validate_inputs(linear),"A8 and W feed Linear");
  ForwardController reset_type;BufferRef old_type=test::ref(Buffer::TYPE_ROWS),new_type=test::ref(Buffer::TYPE_ROWS,0,2);
  test::require(reset_type.reserve(old_type,0,3,Content::F32)&&reset_type.type_row(old_type,1),"reset type fixture");
  reset_type.reset();
  test::require(!reset_type.type_valid(old_type,1)&&!reset_type.acquire_type_read(old_type,1),"reset invalidates old type row");
  test::require(!reset_type.reserve(old_type,0,3,Content::F32),"reset cannot reuse old type epoch");
  test::require(reset_type.reserve(new_type,0,3,Content::F32)&&reset_type.type_row(new_type,1),"reset allows next type epoch");
  ForwardController reset_inplace;BufferRef old_score=test::ref(Buffer::SCORE_PROB),new_score=test::ref(Buffer::SCORE_PROB,0,2);
  test::require(reset_inplace.reserve(old_score,0,2,Content::SCORE)&&reset_inplace.cover(old_score,0,0,2)&&reset_inplace.publish(old_score,0,true),"reset inplace fixture");
  test::require(reset_inplace.begin_inplace(old_score,new_score,0,2,Content::PROB),"begin reset inplace");
  test::require(!reset_inplace.cover(old_score,0,0,1),"old epoch cannot cover inplace");
  test::require(reset_inplace.cover(new_score,0,0,1)&&!reset_inplace.cover(new_score,0,0,1),"new epoch cover once");
  reset_inplace.reset();
  test::require(!reset_inplace.ready(old_score,0)&&!reset_inplace.ready(new_score,0),"reset invalidates both inplace refs");
  test::require(!reset_inplace.acquire_read(old_score,0,Content::SCORE)&&!reset_inplace.acquire_read(new_score,0,Content::PROB),"reset forbids both inplace reads");
  test::require(!reset_inplace.reserve(old_score,0,2,Content::SCORE),"old epoch cannot reserve after reset");
  test::require(!reset_inplace.reserve(new_score,0,2,Content::SCORE),"aborted in-place epoch cannot be reused");
  BufferRef fresh_score=test::ref(Buffer::SCORE_PROB,0,3);
  test::require(reset_inplace.reserve(fresh_score,0,2,Content::SCORE)&&reset_inplace.cover(fresh_score,0,0,2)&&reset_inplace.publish(fresh_score,0,true),"fresh epoch can publish after reset");
  test::require(!reset_inplace.ready(old_score,0)&&!reset_inplace.ready(new_score,0),"old refs stay invalid after fresh publication");
}
